// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 time) public {
        value = bound(value, 0, 100 ether);
        vm.assume(time > c.pastBlockTime());
        vm.warp(time);
        vm.deal(address(this), value);

        (bool success,) = address(c).call{value: value}("");

        assertTrue(success == (value == 10 ether));
    }
}

